const supportedUiRoles = new Set(['physician', 'nurse', 'pharmacist', 'technician', 'therapist', 'dietitian', 'social-worker', 'clerk', 'administrator']);
const state = { runtime: null, token: null, csrfToken: null, authError: null, patients: [], selectedPatientId: localStorage.getItem('emr-selected-patient') || 'P0001001', route: 'dashboard', recordId: null, recordVersion: null, recordSoap: null, latestOrderId: null, activeFhir: null, hospitalModule: 'reception', role: localStorage.getItem('emr-demo-role') || 'physician', practitionerId: null, authenticated: false };
const app = document.querySelector('#app');
const strip = document.querySelector('#patient-strip');
const toast = document.querySelector('#toast');
const publicBasePath = new URL('.', import.meta.url).pathname.replace(/\/$/, '');

function appPath(path) { return `${publicBasePath}${path.startsWith('/') ? path : `/${path}`}`; }

function escapeHtml(value = '') { return String(value).replace(/[&<>'"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', "'": '&#39;', '"': '&quot;' })[c]); }
function statusClass(status) { return ['有効', 'signed', 'completed', 'approved', 'accepted', 'acknowledged', 'on-duty', 'active', 'admitted', 'discharged', 'connected', 'dispensed', 'validated', 'final', 'verified', 'ready', 'issued', 'reported', 'resolved'].includes(status) ? 'status-ok' : ['確認待ち', 'requested', 'submitted', 'accepted-for-delivery', 'queued', 'draft', 'reserved', 'reviewing', 'pending', 'scheduled', 'planned', 'processing', 'coding', 'planning', 'assessment', 'clarification-needed', 'review-required', 'preliminary', 'monitoring', 'in-progress'].includes(status) ? 'status-warn' : 'status-info'; }
function ageOf(birthDate) { const today = new Date('2026-09-11T00:00:00+09:00'); const birth = new Date(`${birthDate}T00:00:00+09:00`); let age = today.getFullYear() - birth.getFullYear(); if (today.getMonth() < birth.getMonth() || (today.getMonth() === birth.getMonth() && today.getDate() < birth.getDate())) age -= 1; return age; }
function showToast(message, error = false) { toast.textContent = message; toast.classList.toggle('error', error); toast.classList.add('show'); setTimeout(() => toast.classList.remove('show'), 2800); }

async function api(path, options = {}) {
  if (!state.token && state.runtime?.mode !== 'production') {
    const form = new URLSearchParams({ grant_type: 'client_credentials', client_id: 'demo-web', scope: 'system/*.read system/*.write' });
    const response = await fetch(appPath('/oauth/token'), { method: 'POST', headers: { 'Content-Type': 'application/x-www-form-urlencoded' }, body: form });
    const payload = await response.json();
    if (!response.ok || !payload.access_token) throw new Error(payload.detail || 'デモトークンを取得できません。');
    state.token = payload.access_token;
  }
  const method = String(options.method || 'GET').toUpperCase();
  const headers = { 'Content-Type': 'application/json', 'X-Request-ID': `WEB-${Date.now()}`, ...(options.headers || {}) };
  if (state.runtime?.mode === 'production') {
    if (!['GET', 'HEAD', 'OPTIONS'].includes(method) && state.csrfToken) headers['X-CSRF-Token'] = state.csrfToken;
  } else Object.assign(headers, { Authorization: `Bearer ${state.token}`, 'X-Practitioner-ID': 'PRACT-001', 'X-Demo-Role': state.role });
  if (!['GET', 'HEAD', 'OPTIONS'].includes(method) && !headers['Idempotency-Key']) headers['Idempotency-Key'] = `WEB-${crypto.randomUUID()}`;
  const requestOptions = { ...options, headers }; delete requestOptions._retried;
  const response = await fetch(appPath(path), requestOptions);
  if (response.status === 401) {
    state.token = null; state.csrfToken = null;
    if (state.runtime?.mode !== 'production' && !options._retried) return api(path, { ...options, headers, _retried: true });
    state.authenticated = false;
  }
  const body = await response.json();
  if (!response.ok) throw new Error(body.detail || body.issue?.[0]?.diagnostics || 'APIエラー');
  return body;
}

function applyRuntimeLabels() {
  const production = state.runtime?.mode === 'production';
  document.querySelector('#environment-badge').textContent = production ? 'PRODUCTION' : 'DEMO';
  document.querySelector('#facility-environment').textContent = production ? '公開候補 / 架空データ専用 / 外部OIDC' : '架空病院 / TENANT-KTUMH-DEMO';
}

function applySessionIdentity(user) {
  const claimedRole = user?.role;
  if (supportedUiRoles.has(claimedRole)) state.role = claimedRole;
  state.practitionerId = user?.practitionerId || null;
  const displayName = String(user?.name || user?.sub || '認証済み利用者');
  document.querySelector('#user-name').textContent = displayName;
  document.querySelector('#user-initial').textContent = displayName.slice(0, 1);
}

async function beginProductionLogin() {
  const returnTo = `/${location.hash || '#/dashboard'}`;
  location.assign(appPath(`/auth/login?returnTo=${encodeURIComponent(returnTo)}`));
}

async function logoutSession() {
  let logoutUrl = null;
  if (state.runtime?.mode === 'production') {
    const response = await fetch(appPath('/auth/logout'), { method: 'POST', headers: { 'X-CSRF-Token': state.csrfToken || '' } });
    if (response.ok) logoutUrl = (await response.json()).logoutUrl;
  }
  state.token = null; state.csrfToken = null; state.authenticated = false; state.practitionerId = null; state.patients = [];
  if (state.runtime?.mode === 'demo') sessionStorage.setItem('emr-demo-authenticated', 'false');
  if (logoutUrl) { location.assign(logoutUrl); return; }
  renderLogin();
}

function selectedPatient() { return state.patients.find((p) => p.id === state.selectedPatientId) || state.patients[0]; }
function heading(title, description, actions = '') { return `<div class="page-heading"><div><h1>${title}</h1><p>${description}</p></div><div class="heading-actions">${actions}</div></div>`; }
function patientStrip(patient) {
  if (!patient || ['dashboard', 'patients'].includes(state.route)) { strip.classList.add('hidden'); strip.innerHTML = ''; return; }
  strip.classList.remove('hidden');
  strip.innerHTML = `<div class="patient-avatar">${escapeHtml(patient.name.split(' ')[0][0])}</div><div class="patient-ident"><strong>${escapeHtml(patient.name)}</strong><small>${patient.id} ・ ${escapeHtml(patient.kana)}</small></div><div class="patient-facts"><span>${ageOf(patient.birthDate)}歳 / ${patient.gender === 'female' ? '女性' : '男性'}</span><span>${escapeHtml(patient.careContext?.careSetting || '外来')}・${escapeHtml(patient.careContext?.location || patient.room)}</span><span>保険 <b>${escapeHtml(patient.insurance.status)}</b></span><span>${patient.allergies.length ? `アレルギー：${escapeHtml(patient.allergies.join('・'))}` : 'アレルギーなし'}</span></div>`;
}
function setActiveNav() { document.querySelectorAll('#main-nav a').forEach((a) => a.classList.toggle('active', a.dataset.route === state.route)); }
function bindAction(selector, handler) { document.querySelectorAll(selector).forEach((el) => el.addEventListener('click', handler)); }
function patientName(id) { return state.patients.find((patient) => patient.id === id)?.name || id || '未割当'; }
function dateTime(value) { return value ? value.slice(0, 16).replace('T', ' ') : '未定'; }
function roleName(role) { return ({ physician: '医師', nurse: '看護師', pharmacist: '薬剤師', technician: '技師', therapist: '療法士', dietitian: '管理栄養士', 'social-worker': '医療ソーシャルワーカー', clerk: '医事', administrator: '管理者' })[role] || role; }
function updateRoleLabel() { const label = document.querySelector('#role-label'); if (label) label.textContent = `${state.runtime?.mode === 'production' ? 'OIDC' : 'DEMO'} / ${roleName(state.role)}`; }

async function ensurePatients() { if (!state.patients.length) state.patients = (await api('/api/v1/patients')).items; }

async function renderDashboard() {
  const data = await api('/api/v1/dashboard'); state.patients = data.patients;
  app.innerHTML = `${heading('本日の診療', '2026年9月11日（金）・外来業務の進行状況', '<button class="secondary" data-go="patients">患者を検索</button><button class="primary" data-go="encounter">診療を開始</button>')}
  <section class="metrics">
    <article class="card metric"><small>診察待ち</small><strong>${data.counts.waiting}</strong><span>♙</span></article>
    <article class="card metric"><small>未確定カルテ</small><strong>${data.counts.unsigned}</strong><span>▤</span></article>
    <article class="card metric"><small>検査結果待ち</small><strong>${data.counts.pendingLabs}</strong><span>⌁</span></article>
    <article class="card metric"><small>医療DXエラー</small><strong>${data.counts.dxErrors}</strong><span>⇄</span></article>
  </section>
  <section class="dashboard-grid">
    <article class="card"><div class="card-header"><h2>本日の患者</h2><button class="ghost button-small" data-go="patients">一覧を見る</button></div><div class="table-wrap"><table><thead><tr><th>患者</th><th>診療科</th><th>予約</th><th>状態</th><th></th></tr></thead><tbody>${data.patients.map((p) => `<tr class="clickable-row" data-patient="${p.id}"><td class="name-cell"><strong>${escapeHtml(p.name)}</strong><small>${p.id}</small></td><td>${escapeHtml(p.department)}</td><td>${escapeHtml(p.nextAppointment)}</td><td><span class="status ${statusClass(p.status)}">${escapeHtml(p.status)}</span></td><td>›</td></tr>`).join('')}</tbody></table></div></article>
    <div class="stack"><article class="card"><div class="card-header"><h2>クイック操作</h2></div><div class="card-body quick-list">
      <button data-go="encounter"><span><strong>新規カルテ</strong><small>SOAP記録を作成</small></span><b>＋</b></button>
      <button data-go="prescriptions"><span><strong>処方オーダ</strong><small>電子処方箋へ連携</small></span><b>℞</b></button>
      <button data-go="labs"><span><strong>検査オーダ</strong><small>検査部門へ送信</small></span><b>⌁</b></button>
      <button data-go="fhir"><span><strong>FHIR文書</strong><small>送受信・内容確認</small></span><b>{ }</b></button>
    </div></article><article class="card"><div class="card-header"><h2>連携サービス</h2></div><div class="card-body integration-list">${['オンライン資格確認', '電子処方箋', '電カル情報共有', '部門システム'].map((x) => `<div class="integration-row"><span>${x}</span><span class="status status-ok">模擬正常</span></div>`).join('')}</div></article></div>
  </section>`;
  bindPatientRows();
}

async function renderPatients() {
  await ensurePatients();
  app.innerHTML = `${heading('患者一覧', '患者ID・氏名・カナで検索し、診療対象を選択します。', '<button class="primary" id="new-encounter">選択患者の診療を開始</button>')}
  <div class="toolbar"><div class="search"><label class="sr-only" for="patient-search">患者検索</label><input id="patient-search" placeholder="患者ID、氏名、カナを入力"></div><select id="department-filter" aria-label="診療科"><option value="">すべての診療科</option>${[...new Set(state.patients.map((patient) => patient.department))].sort().map((department) => `<option>${escapeHtml(department)}</option>`).join('')}</select><select id="setting-filter" aria-label="診療場面"><option value="">すべての診療場面</option>${[...new Set(state.patients.map((patient) => patient.careContext?.careSetting).filter(Boolean))].map((setting) => `<option>${escapeHtml(setting)}</option>`).join('')}</select><button class="ghost" id="clear-search">クリア</button></div>
  <article class="card"><div class="table-wrap"><table><thead><tr><th>患者ID</th><th>患者氏名</th><th>生年月日 / 年齢</th><th>診療科</th><th>診療場面・場所</th><th>資格</th><th>アラート</th><th>状態</th></tr></thead><tbody id="patient-body"></tbody></table></div></article>`;
  const tbody = document.querySelector('#patient-body');
  const draw = () => {
    const q = document.querySelector('#patient-search').value.toLowerCase(); const dept = document.querySelector('#department-filter').value; const setting = document.querySelector('#setting-filter').value;
    const items = state.patients.filter((p) => (!q || [p.id,p.name,p.kana].some((v) => v.toLowerCase().includes(q))) && (!dept || p.department === dept) && (!setting || p.careContext?.careSetting === setting));
    tbody.innerHTML = items.map((p) => `<tr class="clickable-row ${p.id === state.selectedPatientId ? 'selected' : ''}" data-patient="${p.id}"><td>${p.id}</td><td class="name-cell"><strong>${escapeHtml(p.name)}</strong><small>${escapeHtml(p.kana)}</small></td><td>${p.birthDate}<br><small>${ageOf(p.birthDate)}歳</small></td><td>${escapeHtml(p.department)}</td><td><b>${escapeHtml(p.careContext?.careSetting || '外来')}</b><br><small>${escapeHtml(p.careContext?.location || p.room)}</small></td><td><span class="status ${statusClass(p.insurance.status)}">${escapeHtml(p.insurance.status)}</span></td><td>${[...p.allergies,...p.alerts].map((a) => `<span class="tag tag-danger">${escapeHtml(a)}</span>`).join('') || '—'}</td><td><span class="status ${statusClass(p.status)}">${escapeHtml(p.status)}</span></td></tr>`).join('');
    bindPatientRows();
  };
  document.querySelector('#patient-search').addEventListener('input', draw); document.querySelector('#department-filter').addEventListener('change', draw); document.querySelector('#setting-filter').addEventListener('change', draw);
  document.querySelector('#clear-search').addEventListener('click', () => { document.querySelector('#patient-search').value = ''; document.querySelector('#department-filter').value = ''; document.querySelector('#setting-filter').value = ''; draw(); });
  document.querySelector('#new-encounter').addEventListener('click', () => go('encounter')); draw();
}

function bindPatientRows() { bindAction('[data-patient]', (event) => { state.selectedPatientId = event.currentTarget.dataset.patient; state.recordId = null; state.recordVersion = null; state.recordSoap = null; localStorage.setItem('emr-selected-patient', state.selectedPatientId); go('records'); }); }

async function renderRecords() {
  await ensurePatients(); const patient = selectedPatient(); const data = await api(`/api/v1/patients/${patient.id}/records`);
  app.innerHTML = `${heading('カルテ一覧', `${escapeHtml(patient.name)}さんの診療記録`, '<button class="primary" data-go="encounter">新規カルテ</button>')}
  <div class="toolbar"><div class="search"><input id="record-search" aria-label="カルテ検索" placeholder="SOAP本文・診療科・作成者を検索"></div><select aria-label="期間"><option>全期間</option><option>過去3か月</option><option>過去1年</option></select></div>
  <div class="record-list">${data.items.length ? data.items.map((r) => `<article class="card record-card"><div class="record-date"><strong>${r.occurredAt.slice(0,10)}</strong><small>${r.occurredAt.slice(11,16)} / ${escapeHtml(r.department)}</small></div><div><h3>${escapeHtml(r.soap.assessment || '診療記録')}</h3><p><b>S：</b>${escapeHtml(r.soap.subjective)}<br><b>P：</b>${escapeHtml(r.soap.plan)}</p></div><div><span class="status ${statusClass(r.status)}">${r.status === 'signed' ? '確定済' : '下書き'}</span><br><small>${escapeHtml(r.author)}</small></div></article>`).join('') : '<div class="card empty">診療記録はありません。</div>'}</div>`;
}

async function renderEncounter() {
  await ensurePatients(); const patient = selectedPatient(); const summary = await api(`/api/v1/patients/${patient.id}/summary`);
  app.innerHTML = `${heading('診療記録', 'SOAP入力、オーダ、文書・サマリーを患者コンテキスト内で管理します。', '<button class="ghost" id="save-draft">下書き保存</button><button class="primary" id="sign-record">カルテを確定</button>')}
  <div class="tabs"><button class="active" data-tab="soap">SOAP</button><button data-tab="injection">注射</button><button data-tab="imaging">画像・文書</button><button data-tab="summary">サマリー</button></div>
  <section class="encounter-grid"><article class="card"><div id="encounter-panel" class="card-body"></div></article>
  <aside class="stack"><article class="card"><div class="card-header"><h3>患者サマリー</h3><span class="status status-info">${escapeHtml(summary.patientContext?.careSetting || '外来')}</span></div><div class="card-body summary-list"><div class="summary-item"><small>現在地・次の対応</small><p>${escapeHtml(summary.patientContext?.location || patient.room)}<br>${escapeHtml(summary.patientContext?.nextAction || '診療内容を確認')}</p></div><div class="summary-item"><small>アレルギー・臨床リスク</small><p>${(summary.patientContext?.clinicalRisks || patient.allergies).map((a) => `<span class="tag tag-danger">${escapeHtml(a)}</span>`).join('') || 'なし'}</p></div><div class="summary-item"><small>現病・プロブレム</small><p>${summary.conditions.map((condition) => `${escapeHtml(condition.display)}（${escapeHtml(condition.code)}）`).join('<br>') || 'なし'}</p></div><div class="summary-item"><small>担当チーム</small><p>${summary.careTeam?.members.map((member) => `${escapeHtml(member.role)}：${escapeHtml(member.name)}`).join('<br>') || '未編成'}</p></div><div class="summary-item"><small>継続処方</small><p>${summary.medications.map((m) => escapeHtml(m.medicationDisplay)).join('<br>') || 'なし'}</p></div><div class="summary-item"><small>部門予定・実施</small><p>${summary.hospitalActivities.slice(0, 4).map((item) => `${escapeHtml(item.workType)}：${escapeHtml(workflowLabels[item.status] || item.status)}`).join('<br>') || 'なし'}</p></div><div class="summary-item"><small>同意状況</small><p>${summary.consents.map((item) => `${escapeHtml(item.purpose)}：${escapeHtml(item.status)}`).join('<br>') || '未確認'}</p></div><div class="summary-item"><small>直近検査</small><p>${summary.labs.map((l) => `${escapeHtml(l.name)}：${escapeHtml(l.result || '結果待ち')}`).join('<br>') || 'なし'}</p></div></div></article><div class="notice-box warning-box"><strong>確定前確認</strong><p>確定後の直接編集は不可とし、訂正履歴を追加する設計です。モックでは新規作成と確定を再現します。</p></div></aside></section>`;
  drawEncounterTab('soap');
  bindAction('[data-tab]', (event) => { document.querySelectorAll('[data-tab]').forEach((b) => b.classList.remove('active')); event.currentTarget.classList.add('active'); drawEncounterTab(event.currentTarget.dataset.tab); });
  document.querySelector('#save-draft').addEventListener('click', saveSoap);
  document.querySelector('#sign-record').addEventListener('click', async () => {
    if (!state.recordId) await saveSoap();
    if (!state.recordId || !state.recordVersion) return;
    if (soapFieldsChanged()) return showToast('保存後に内容が変更されています。下書きを作り直してから確定してください。', true);
    try {
      await api(`/api/v1/records/${state.recordId}/sign`, { method: 'PUT', body: JSON.stringify({ version: state.recordVersion }) });
      state.recordId = null; state.recordVersion = null; state.recordSoap = null;
      showToast('診療記録を確定しました'); await renderRecords();
    } catch (error) { showToast(error.message, true); }
  });
}

function drawEncounterTab(tab) {
  const panel = document.querySelector('#encounter-panel');
  if (tab === 'soap') {
    const soap = state.recordSoap || { subjective: '朝から咳と痰があります。発熱はありません。', objective: '体温36.7℃、SpO2 98%、呼吸音に明らかな異常なし。', assessment: '急性上気道炎を疑う。', plan: '対症療法。悪化時または1週間以上続く場合は再診。' };
    const locked = state.recordId ? ' disabled' : '';
    panel.innerHTML = `<div class="soap-grid"><label class="soap-field"><b><span>S</span>Subjective / 主観</b><textarea id="soap-s"${locked}>${escapeHtml(soap.subjective)}</textarea></label><label class="soap-field"><b><span>O</span>Objective / 客観</b><textarea id="soap-o"${locked}>${escapeHtml(soap.objective)}</textarea></label><label class="soap-field"><b><span>A</span>Assessment / 評価</b><textarea id="soap-a"${locked}>${escapeHtml(soap.assessment)}</textarea></label><label class="soap-field"><b><span>P</span>Plan / 計画</b><textarea id="soap-p"${locked}>${escapeHtml(soap.plan)}</textarea></label></div>${state.recordId ? '<div class="compact-note">保存済み下書きを表示しています。内容は確定までロックされています。</div>' : ''}`;
  }
  if (tab === 'injection') { panel.innerHTML = `<h3>注射オーダ</h3><div class="field-grid"><label>注射薬名<input id="inj-med" value="生理食塩液 100mL（架空）"></label><label>投与量<input id="inj-dose" value="100mL"></label><label>投与経路<select id="inj-route"><option>静脈内点滴</option><option>皮下注射</option><option>筋肉内注射</option></select></label><label>開始予定<input id="inj-time" type="datetime-local" value="2026-09-11T14:00"></label></div><div class="form-actions"><button class="primary" id="submit-injection">注射オーダ登録</button></div>`; document.querySelector('#submit-injection').addEventListener('click', submitInjection); }
  if (tab === 'imaging') { panel.innerHTML = `<h3>画像・文書管理</h3><div class="field-grid"><label>種別<select id="doc-type"><option>画像オーダ</option><option>紹介状</option><option>同意書</option><option>検査報告書</option></select></label><label>名称<input id="doc-title" value="胸部X線 2方向"></label></div><label>臨床情報<textarea id="doc-note">咳嗽の精査。肺野の異常陰影の有無を確認。</textarea></label><div class="form-actions"><button class="primary" id="submit-document">登録する</button></div>`; document.querySelector('#submit-document').addEventListener('click', submitDocument); }
  if (tab === 'summary') { panel.innerHTML = `<h3>退院時サマリー・診療情報提供書</h3><div class="field-grid"><label>文書種別<select id="summary-type"><option>診療情報提供書</option><option>退院時サマリー</option></select></label><label>紹介先・宛先<input id="summary-to" value="地域医療センター 御中"></label></div><label>傷病名<textarea id="summary-condition">急性上気道炎（疑い）</textarea></label><label>経過・治療内容<textarea id="summary-course">外来で対症療法を開始。経過観察中。</textarea></label><div class="form-actions"><button class="primary" id="submit-summary">FHIR文書として作成</button></div>`; document.querySelector('#submit-summary').addEventListener('click', submitSummary); }
}

function currentSoap() {
  const fields = ['s','o','a','p'].map((x) => document.querySelector(`#soap-${x}`));
  if (fields.some((field) => !field)) return null;
  return { subjective: fields[0].value, objective: fields[1].value, assessment: fields[2].value, plan: fields[3].value };
}
function soapFieldsChanged() { const soap = currentSoap(); return Boolean(soap && state.recordSoap && JSON.stringify(soap) !== JSON.stringify(state.recordSoap)); }
async function saveSoap() {
  if (state.recordId) return showToast('下書きは保存済みです。確定するか、患者一覧から新しい記録を開始してください。', true);
  const soap = currentSoap(); if (!soap) return showToast('SOAPタブで保存してください', true);
  try {
    const result = await api('/api/v1/records', { method: 'POST', body: JSON.stringify({ patientId: state.selectedPatientId, department: selectedPatient().department, author: '佐藤 医師', soap }) });
    state.recordId = result.id; state.recordVersion = result.version; state.recordSoap = structuredClone(result.soap);
    drawEncounterTab('soap'); document.querySelector('#save-draft').disabled = true;
    showToast(`下書きを保存しました：${result.id}`);
  } catch (error) { showToast(error.message, true); }
}
